items.solution:
function buildAdjacencyList(edges) {
  const adj = {};
  for (const [from, to] of edges) {
    if (!(from in adj)) adj[from] = [];
    if (!(to in adj)) adj[to] = [];
    adj[from].push(to);
  }
  return adj;
}

