function buildWeightedAdjacencyList(edges) {
  const adj = {};
  for (const [from, to, weight] of edges) {
    if (!(from in adj)) adj[from] = [];
    if (!(to in adj)) adj[to] = [];
    adj[from].push({ to, weight });
  }
  return adj;
}

