items.solution:
function dijkstraShortestPath(adj, start, end) {
  const costSoFar = new Map([[start, 0]]);
  const cameFrom = new Map();
  const unvisited = new Set(Object.keys(adj));

  while (unvisited.size > 0) {
    let current = null;
    let currentCost = Infinity;
    for (const node of unvisited) {
      const cost = costSoFar.has(node) ? costSoFar.get(node) : Infinity;
      if (cost < currentCost) {
        current = node;
        currentCost = cost;
      }
    }
    if (current === null || currentCost === Infinity) break;
    unvisited.delete(current);
    if (current === end) break;

    for (const edge of adj[current] || []) {
      const candidate = currentCost + edge.weight;
      const known = costSoFar.has(edge.to) ? costSoFar.get(edge.to) : Infinity;
      if (candidate < known) {
        costSoFar.set(edge.to, candidate);
        cameFrom.set(edge.to, current);
      }
    }
  }

  if (!costSoFar.has(end)) return null;
  const path = [];
  let node = end;
  while (node !== undefined) {
    path.push(node);
    node = cameFrom.get(node);
  }
  return { path: path.reverse(), cost: costSoFar.get(end) };
}

