function hasCycle(adj) {
  const WHITE = 0, GRAY = 1, BLACK = 2;
  const color = {};
  for (const node of Object.keys(adj)) color[node] = WHITE;

  function visit(node) {
    color[node] = GRAY;
    for (const neighbor of adj[node] || []) {
      if (color[neighbor] === GRAY) return true;
      if (color[neighbor] === WHITE && visit(neighbor)) return true;
    }
    color[node] = BLACK;
    return false;
  }

  for (const node of Object.keys(adj)) {
    if (color[node] === WHITE && visit(node)) return true;
  }
  return false;
}

